var e={maxFlow:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Descubra o maior fluxo volumétrico (mm³/s) que o seu hotend consegue sustentar - aumentando o fluxo enquanto observa a carga do StallGuard do extrusor para flagrar o momento em que a engrenagem patina. Visualize o plano primeiro; o teste ao vivo aquece e extruda, então prepare a impressora antes de executar.`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Ajuda`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Sobre o Max-Flow`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Fechar`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Como usar`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Defina a temperatura do teste e o diâmetro do seu filamento (escolha um hotend para preencher automaticamente).`}},{t:0,b:{t:2,i:[{t:3}],s:`Visualize o plano - ele mostra cada passo de fluxo e quanto filamento empurra.`}},{t:0,b:{t:2,i:[{t:3}],s:`Marque a lista de segurança e execute o teste ao vivo (aquece + extruda).`}},{t:0,b:{t:2,i:[{t:3}],s:`Leia o fluxo máximo sustentado e copie o valor sugerido para o fatiador.`}}],topics:{howItWorks:{title:{t:0,b:{t:2,i:[{t:3}],s:`Como o teste funciona`}},body:{t:0,b:{t:2,i:[{t:3}],s:`O extrusor empurra o filamento em um fluxo volumétrico que aumenta de forma constante. Enquanto a engrenagem dentada agarra bem, a leitura de carga do StallGuard permanece estável; quando começa a patinar, as leituras passam a oscilar. O maior fluxo alcançado antes desse salto é o seu fluxo máximo sustentável. A rampa para assim que o deslizamento é detectado, então nenhum filamento é triturado além do primeiro deslizamento.`}}},stallguard:{title:{t:0,b:{t:2,i:[{t:3}],s:`Detecção de deslizamento por StallGuard`}},body:{t:0,b:{t:2,i:[{t:3}],s:`O StallGuard é um recurso do driver TMC que reporta a carga do motor. Este teste o amostra muitas vezes por passo de fluxo e procura uma elevação súbita na dispersão (IQR) ou na variação (CV) - a assinatura da engrenagem perdendo aderência. Os limiares vêm de um perfil por driver. Observação: em um extrusor com TMC2209 isso usa o caminho experimental SG4, então trate a primeira execução como uma calibração.`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`Segurança`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Este é um teste quente e em movimento que faz o extrusor patinar de propósito. Carregue o filamento, garanta que o bico esteja livre (sobre a mesa ou uma área de descarte) e fique por perto. A execução é recusada enquanto a impressora estiver imprimindo, e o aquecedor é sempre desligado ao terminar.`}}},slicer:{title:{t:0,b:{t:2,i:[{t:3}],s:`Usando o resultado`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Coloque o valor sugerido na "velocidade volumétrica máxima" do seu fatiador (por filamento). O número conservador (80% do máximo medido) é um limite seguro para o dia a dia; o número equilibrado (90%) força um pouco mais. Temperaturas mais altas no hotend costumam elevar o fluxo alcançável.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glossário`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{flow:{term:{t:0,b:{t:2,i:[{t:3}],s:`Fluxo volumétrico`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Quanto plástico o hotend derrete por segundo (mm³/s) - o real limite de velocidade para impressões rápidas.`}}},stallguard:{term:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Um sinal do driver TMC que reporta a carga mecânica do motor, usado aqui para detectar o deslizamento do extrusor.`}}},slip:{term:{t:0,b:{t:2,i:[{t:3}],s:`Deslizamento`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Quando a engrenagem do extrusor não consegue mais agarrar o filamento rápido o suficiente e patina - o teto do fluxo.`}}},meltzone:{term:{t:0,b:{t:2,i:[{t:3}],s:`Zona de fusão`}},def:{t:0,b:{t:2,i:[{t:3}],s:`O comprimento aquecido do hotend; uma zona de fusão mais longa (ex.: Volcano) sustenta um fluxo maior.`}}}}},params:{title:{t:0,b:{t:2,i:[{t:3}],s:`Parâmetros do teste`}},temperature:{t:0,b:{t:2,i:[{t:3}],s:`Temperatura (°C)`}},filamentDiameter:{t:0,b:{t:2,i:[{t:3}],s:`Ø do filamento (mm)`}},hotend:{t:0,b:{t:2,i:[{t:3}],s:`Hotend (opcional)`}},hotendNone:{t:0,b:{t:2,i:[{t:3}],s:`- nenhum -`}},hotendHint:{t:0,b:{t:2,i:[{t:3,v:`Esperado ~`},{t:4,k:`flow`},{t:3,v:` mm³/s`}]}},startFlow:{t:0,b:{t:2,i:[{t:3}],s:`Fluxo inicial (mm³/s)`}},endFlow:{t:0,b:{t:2,i:[{t:3}],s:`Fluxo final (mm³/s)`}},stepFlow:{t:0,b:{t:2,i:[{t:3}],s:`Passo (mm³/s)`}},samples:{t:0,b:{t:2,i:[{t:3}],s:`Amostras / passo`}},extrudePerStep:{t:0,b:{t:2,i:[{t:3}],s:`Extrusão / passo (mm)`}},driver:{t:0,b:{t:2,i:[{t:3}],s:`Driver do extrusor`}},driverDetected:{t:0,b:{t:2,i:[{t:3}],s:`detectado da impressora`}},autoStealthchop:{t:0,b:{t:2,i:[{t:3}],s:`Ativar StealthChop automaticamente para o teste`}},autoStealthchopHint:{t:0,b:{t:2,i:[{t:3}],s:`Apenas TMC2209/2240: grava temporariamente um stealthchop_threshold no extrusor para que o StallGuard possa ler e o comenta após o teste. Restaura o printer.cfg; reinício do firmware em cada etapa.`}},method:{t:0,b:{t:2,i:[{t:3}],s:`Método de detecção`}},methodHint:{t:0,b:{t:2,i:[{t:3}],s:`O modo Auto usa o StallGuard, recorrendo ao acelerômetro da cabeça de impressão (vibração) quando o StallGuard não consegue ler. O método por acelerômetro é experimental.`}}},method:{auto:{t:0,b:{t:2,i:[{t:3}],s:`Auto`}},stallguard:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard`}},accel:{t:0,b:{t:2,i:[{t:3}],s:`Acelerômetro`}}},plan:{button:{t:0,b:{t:2,i:[{t:3}],s:`Visualizar plano`}},title:{t:0,b:{t:2,i:[{t:3}],s:`Rampa planejada`}},stepCount:{t:0,b:{t:2,i:[{t:4,k:`count`},{t:3,v:` passos`}]}},totalExtrude:{t:0,b:{t:2,i:[{t:4,k:`mm`},{t:3,v:` mm de filamento`}]}},sgField:{t:0,b:{t:2,i:[{t:3,v:`Campo StallGuard: `},{t:4,k:`field`}]}},sgFieldUnknown:{t:0,b:{t:2,i:[{t:3}],s:`Nenhum campo StallGuard conhecido para este driver`}},flowHead:{t:0,b:{t:2,i:[{t:3}],s:`Fluxo (mm³/s)`}},feedrateHead:{t:0,b:{t:2,i:[{t:3}],s:`Avanço (mm/min)`}},warning:{t:0,b:{t:2,i:[{t:3}],s:`O teste ao vivo aquece o hotend e extruda filamento, propositalmente até o ponto de deslizamento. Apenas visualização - nada é executado ainda.`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`Antes de executar - lista de segurança`}},items:[{t:0,b:{t:2,i:[{t:3}],s:`O filamento está carregado e avança livremente.`}},{t:0,b:{t:2,i:[{t:3}],s:`O bico está livre - sobre a mesa ou uma lixeira, não no ar sobre peças.`}},{t:0,b:{t:2,i:[{t:3}],s:`Aceito que isto vai triturar/deslizar algum filamento de propósito.`}},{t:0,b:{t:2,i:[{t:3}],s:`Vou ficar com a impressora durante todo o teste.`}}],ack:{t:0,b:{t:2,i:[{t:3}],s:`Fiz tudo acima e a impressora está pronta`}},note:{t:0,b:{t:2,i:[{t:3}],s:`A execução é recusada durante a impressão; o aquecedor é desligado automaticamente ao final.`}}},run:{button:{t:0,b:{t:2,i:[{t:3}],s:`Executar teste ao vivo`}},running:{t:0,b:{t:2,i:[{t:3}],s:`Executando… (aquecendo + extrudando)`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`Iniciar o teste de max-flow ao vivo?`}},confirmBody:{t:0,b:{t:2,i:[{t:3,v:`Isto aquece o hotend a `},{t:4,k:`temp`},{t:3,v:` °C e extruda até `},{t:4,k:`mm`},{t:3,v:` mm de filamento, aumentando o fluxo até o extrusor patinar.`}]}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Executar agora`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Cancelar`}},busy:{t:0,b:{t:2,i:[{t:3}],s:`Recusado: a impressora está ocupada (imprimindo ou pausada). Tente novamente quando estiver ociosa.`}},error:{t:0,b:{t:2,i:[{t:3}],s:`O teste falhou.`}},noSg:{t:0,b:{t:2,i:[{t:3}],s:`Nenhuma amostra do StallGuard foi lida - o resultado de deslizamento pode não ser confiável. O campo SG ao vivo do driver provavelmente precisa de ajuste para este modelo.`}},progress:{t:0,b:{t:2,i:[{t:3,v:`Passo `},{t:4,k:`step`},{t:3,v:`/`},{t:4,k:`total`},{t:3,v:` - `},{t:4,k:`flow`},{t:3,v:` mm³/s`}]}},starting:{t:0,b:{t:2,i:[{t:3}],s:`Aquecendo / iniciando…`}},abort:{t:0,b:{t:2,i:[{t:3}],s:`Abortar execução`}},cancelling:{t:0,b:{t:2,i:[{t:3}],s:`Abortando…`}},cancelled:{t:0,b:{t:2,i:[{t:3}],s:`Execução abortada - o aquecedor foi desligado.`}},reattached:{t:0,b:{t:2,i:[{t:3}],s:`Reconectado: este resultado terminou enquanto a página estava ausente.`}},failed:{t:0,b:{t:2,i:[{t:3}],s:`A execução do max-flow falhou.`}},abortNote:{t:0,b:{t:2,i:[{t:3}],s:`Abortar sempre desliga o aquecedor.`}},parkNote:{t:0,b:{t:2,i:[{t:3}],s:`Antes de aquecer, a impressora faz o homing (se necessário) e centraliza o bico para uma visão clara.`}},phase:{enabling:{t:0,b:{t:2,i:[{t:3}],s:`Ativando o StealthChop…`}},homing:{t:0,b:{t:2,i:[{t:3}],s:`Fazendo o homing da impressora…`}},centering:{t:0,b:{t:2,i:[{t:3}],s:`Centralizando o bico…`}},heating:{t:0,b:{t:2,i:[{t:3}],s:`Aquecendo o hotend…`}},checking:{t:0,b:{t:2,i:[{t:3}],s:`Verificando o sinal do StallGuard…`}},ramp:{t:0,b:{t:2,i:[{t:3}],s:`Aumentando o fluxo…`}},reverting:{t:0,b:{t:2,i:[{t:3}],s:`Restaurando a configuração…`}}},step:{home:{t:0,b:{t:2,i:[{t:3}],s:`Homing`}},center:{t:0,b:{t:2,i:[{t:3}],s:`Centralizar`}},heat:{t:0,b:{t:2,i:[{t:3}],s:`Aquecer`}},check:{t:0,b:{t:2,i:[{t:3}],s:`Verificar`}},ramp:{t:0,b:{t:2,i:[{t:3}],s:`Rampa`}}}},camera:{title:{t:0,b:{t:2,i:[{t:3}],s:`Câmera ao vivo`}},live:{t:0,b:{t:2,i:[{t:3}],s:`AO VIVO`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Câmera indisponível.`}},willShow:{t:0,b:{t:2,i:[{t:3}],s:`Uma visão da câmera ao vivo mostrará o bico durante o teste.`}},minimize:{t:0,b:{t:2,i:[{t:3}],s:`Minimizar`}},maximize:{t:0,b:{t:2,i:[{t:3}],s:`Maximizar`}},enlarge:{t:0,b:{t:2,i:[{t:3}],s:`Ampliar`}},shrink:{t:0,b:{t:2,i:[{t:3}],s:`Reduzir`}}},result:{title:{t:0,b:{t:2,i:[{t:3}],s:`Resultado`}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:`Fluxo máximo sustentado`}},slipAt:{t:0,b:{t:2,i:[{t:3,v:`Deslizamento detectado em `},{t:4,k:`flow`},{t:3,v:` mm³/s`}]}},noSlip:{t:0,b:{t:2,i:[{t:3}],s:`Sem deslizamento até o maior fluxo testado`}},reason:{t:0,b:{t:2,i:[{t:3}],s:`Detalhe`}},recommendTitle:{t:0,b:{t:2,i:[{t:3}],s:`Valores sugeridos para o fatiador (velocidade volumétrica máxima)`}},conservative:{t:0,b:{t:2,i:[{t:3}],s:`Conservador (80%)`}},balanced:{t:0,b:{t:2,i:[{t:3}],s:`Equilibrado (90%)`}},units:{t:0,b:{t:2,i:[{t:3}],s:`mm³/s`}},fromBefore:{t:0,b:{t:2,i:[{t:3,v:`Medido anteriormente (`},{t:4,k:`at`},{t:3,v:`) - execute novamente para números atualizados.`}]}},unreliableTitle:{t:0,b:{t:2,i:[{t:3}],s:`Não confiável - sem sinal do StallGuard`}},unmeasured:{t:0,b:{t:2,i:[{t:3}],s:`alcançado, não confirmado`}},via:{t:0,b:{t:2,i:[{t:3,v:`Medido via `},{t:4,k:`method`}]}},accelExperimental:{t:0,b:{t:2,i:[{t:3}],s:`Medido por vibração (acelerômetro) - experimental; trate o número como referência, não como um teto exato.`}}},states:{loadingHotends:{t:0,b:{t:2,i:[{t:3}],s:`Carregando hotends…`}}}}};export{e as default};